interface CardPayment {
    void processCardPayment(double amount);
    void refundCardPayment(double amount);
}

interface UPIPayment {
    void processUPIPayment(double amount);
    void refundUPIPayment(double amount);
}

class PaymentGateway implements CardPayment, UPIPayment {

    public void processCardPayment(double amount) {
        System.out.println("Processing card payment of ₹" + amount);
    }

    public void refundCardPayment(double amount) {
        System.out.println("Refunding card payment of ₹" + amount);
    }

    public void processUPIPayment(double amount) {
        System.out.println("Processing UPI payment of ₹" + amount);
    }

    public void refundUPIPayment(double amount) {
        System.out.println("Refunding UPI payment of ₹" + amount);
    }
}

public class Main {
    public static void main(String[] args) {
        PaymentGateway gateway = new PaymentGateway();

        gateway.processCardPayment(1000);
        gateway.refundCardPayment(500);
        gateway.processUPIPayment(2000);
        gateway.refundUPIPayment(1000);
    }
}

